import{_ as a,o as r,c as t,a5 as o}from"./chunks/framework.CsGesDJn.js";const h=JSON.parse('{"title":"Customer Drive with paid S3 overflow","description":"","frontmatter":{},"headers":[],"relativePath":"feature/repository/customer-drive-overflow/spec.md","filePath":"feature/repository/customer-drive-overflow/spec.md"}'),i={name:"feature/repository/customer-drive-overflow/spec.md"};function n(s,e,c,l,d,u){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="customer-drive-with-paid-s3-overflow" tabindex="-1">Customer Drive with paid S3 overflow <a class="header-anchor" href="#customer-drive-with-paid-s3-overflow" aria-label="Permalink to &quot;Customer Drive with paid S3 overflow&quot;">​</a></h1><h2 id="objective" tabindex="-1">Objective <a class="header-anchor" href="#objective" aria-label="Permalink to &quot;Objective&quot;">​</a></h2><p>Owner or workspace Manager connects their Google Drive using a separate agency storage grant. BrandHub creates brandhub-[agency name]/[workspace name]. Existing mapped workspace folders are renamed in place to the current workspace name when next resolved. Folder IDs, not names, determine identity. Creators upload media through BrandHub; content records stay in the database. No Client may configure storage or access OAuth credentials.</p><h2 id="acceptance-criteria" tabindex="-1">Acceptance criteria <a class="header-anchor" href="#acceptance-criteria" aria-label="Permalink to &quot;Acceptance criteria&quot;">​</a></h2><ul><li>Prefer USER_GDRIVE for every new material, including paid agencies. If authoritative available Drive space cannot hold the upload (including staging/promotion), reserve SYSTEM_S3 only for an active unexpired paid plan with sufficient S3 quota.</li><li>Never fall back on OAuth revocation, timeout, unknown capacity, or generic 403. Existing objects never migrate automatically and reads never depend on subscription status.</li><li>No mirrored writes. Persist the selected provider on the upload reservation/material. Retry uses the original provider and idempotency key.</li><li>Drive OAuth uses drive.file by default; opt-in workspace synchronization requests full Drive scope after explicit user consent (see ../../customer-drive-workspace-sync/spec.md). Both use offline access, PKCE and single-use actor/workspace bound state. Refresh tokens encrypted at rest; never returned to the browser or logged. Reconnection must not silently replace a different account that owns existing files.</li><li>Root and workspace folders remain private. Owner/Manager grant Client audience through BrandHub. Creator cannot grant Client audience. Owner has repository operational access in their agency.</li><li>Disconnect now requires a destructive confirmation and permanently deletes the agency BrandHub Drive resources across all workspaces, tombstones materials and releases quota before removing the old account binding. Another account may connect only after successful cleanup. S3 history remains readable. See ../../customer-drive-disconnect/spec.md (2026-10-27).</li><li>Private Drive media is served through short-lived application capabilities, never public sharing or exposing access tokens. Range requests supported for video.</li><li>S3 quota counts S3 objects/reservations only; customer Drive use is not deducted from purchased BrandHub storage. Concurrent reservations cannot oversubscribe capacity known at reservation time.</li></ul><h2 id="ui" tabindex="-1">UI <a class="header-anchor" href="#ui" aria-label="Permalink to &quot;UI&quot;">​</a></h2><p>Storage panel in Repository for Owner/Manager: status, connect/reconnect/disconnect; Creator sees status/recovery guidance only; Client sees none. Preserve existing tokens, light/dark, keyboard support. New keys under library.drive in both vi/en locales: title, connected, disconnected, connect, disconnect, connecting, failed, folder, policy, reconnect, quotaFull.</p><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>Workspace-scoped storage status, authorize, authenticated code completion, disconnect. Browser callback forwards code/state only; backend validates state and membership again. No arbitrary redirect URI. All normal endpoints return ApiResponse. Missing credentials/schema fail closed.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><p>Live OAuth consent, applying production migrations, migration of old SYSTEM_GDRIVE objects, native Google Docs editing and bidirectional external-folder synchronization. External owner edits/deletes may make a material unavailable.</p>',11)])])}const m=a(i,[["render",n]]);export{h as __pageData,m as default};
